import { LoggerLevel, loggerLevelFromName } from "@zudojs/logger";

function levelFromEnv(env) {
  const name = env.LOG_LEVEL?.trim();
  return name ? loggerLevelFromName(name.toLowerCase()) : LoggerLevel.INFO;
}

console.log(levelFromEnv({}), levelFromEnv({ LOG_LEVEL: "debug" }), levelFromEnv({ LOG_LEVEL: " WARN " }));

